const PalaisNotice={
  comment(m,c){if(c.author==='me')return null;const parent=(m.comments||[]).find(x=>x.id===c.parentId);if(parent?.author==='me')return {id:'comment:'+c.id,type:'reply',actor:c.author,momentId:m.id,commentId:c.id,excerpt:m.text.slice(0,80),text:c.text.slice(0,120)};if(m.author==='me')return {id:'comment:'+c.id,type:'comment',actor:c.author,momentId:m.id,commentId:c.id,excerpt:m.text.slice(0,80),text:c.text.slice(0,120)};return null},
  like(m,actor){return m.author==='me'&&actor!=='me'?{id:'like:'+m.id+':'+actor,type:'like',actor,momentId:m.id,excerpt:m.text.slice(0,80)}:null},
  add(list,event){return !event||list.some(x=>x.id===event.id)?list:[...list,{...event,read:false,createdAt:Date.now()}].slice(-200)},
  feedUnread(list){return list.filter(x=>x.type!=='chat'&&!x.read).length}
};
let notices=storedSocial?.notices||[],bannerTimer=null;
function onFeedComment(m,c){notices=PalaisNotice.add(notices,PalaisNotice.comment(m,c))}
function onFeedLike(m,actor){notices=PalaisNotice.add(notices,PalaisNotice.like(m,actor))}
function noticeLabel(n){const who=chatLabel(n.actor);return n.type==='like'?who+'赞了你的朋友圈':n.type==='reply'?who+'回复了你的评论':n.type==='chat'?who+'发来消息':who+'评论了你的朋友圈'}
function notificationDots(){const feed=PalaisNotice.feedUnread(notices),chat=notices.some(n=>n.type==='chat'&&!n.read);document.querySelectorAll('[data-wx="moments"],#openMoments').forEach(b=>{b.classList.toggle('has-news',feed>0);b.title=feed?feed+' 条未读朋友圈互动':''});document.querySelectorAll('[data-tab="wechat"],[data-go="wechat"],[data-wx="chat"]').forEach(b=>b.classList.toggle('has-news',chat||feed>0))}
function feedActivityHTML(){const rows=notices.filter(n=>n.type!=='chat'),n=rows.at(-1),unread=PalaisNotice.feedUnread(notices);return `<button class="feed-activity" id="feedActivity"><span class="activity-icon">❀${unread?'<i class="pink-dot"></i>':''}</span><span><strong>${unread?unread+' 条新互动':n?'最近互动':'朋友圈通知'}</strong><small>${n?escapeHtml(noticeLabel(n)):'点赞、评论和回复会记录在这里'}</small></span><b>›</b></button>`}
function openFeedNotices(){const items=notices.filter(n=>n.type!=='chat').slice().reverse();const d=panel(`<h2>朋友圈互动通知</h2><button class="text-button" id="readAllActivity">全部标为已读</button><div class="activity-list">${items.map(n=>`<button class="activity-item ${n.read?'':'unread'}" data-notice="${n.id}">${avatarHTML('role:'+n.actor,roles.find(r=>r.id===n.actor)?.emoji||'🌷')}<span><strong>${escapeHtml(noticeLabel(n))}</strong><small>「${escapeHtml(n.excerpt||'这条动态')}」</small>${n.text?'<p>'+escapeHtml(n.text)+'</p>':''}<small>${new Date(n.createdAt).toLocaleString('zh-CN')}</small></span>${n.read?'':'<i class="pink-dot"></i>'}</button>`).join('')||'<p class="soft-empty">暂时没有新的互动</p>'}</div><button class="secondary full" id="closeActivity">关闭</button>`);$('#closeActivity').onclick=()=>d.close();$('#readAllActivity').onclick=()=>{notices=notices.map(n=>n.type==='chat'?n:{...n,read:true});saveSocial();d.close();if(isMomentsView())renderMoments();notificationDots()};d.querySelectorAll('[data-notice]').forEach(b=>b.onclick=()=>{const n=notices.find(n=>n.id===b.dataset.notice);n.read=true;saveSocial();d.close();go('moments');const el=[...document.querySelectorAll('[data-moment]')].find(x=>x.dataset.moment===n.momentId);if(el)el.scrollIntoView({block:'start',behavior:'smooth'});else toast('这条动态已移出朋友圈');notificationDots()})}
function markChatSeen(id){let changed=false;notices.forEach(n=>{if(n.type==='chat'&&n.conversationId===id&&!n.read){n.read=true;changed=true}});if(changed){try{saveSocial()}catch{toast('已读状态未保存，请检查存储空间')}notificationDots()}}
function incomingMessage(r,speaker,m){if(isChatView()&&current===r.id)return;notices=PalaisNotice.add(notices,{id:'chat:'+m.id,type:'chat',actor:speaker.id,conversationId:r.id,text:m.content.slice(0,120)});try{saveSocial()}catch{toast('消息已保留，通知保存失败，请检查存储空间')}notificationDots();showPhoneBanner(r,speaker,m);if(isChatView()&&!current)renderChatList()}
function showPhoneBanner(r,speaker,m){const host=$('#phoneBanner');clearTimeout(bannerTimer);host.hidden=false;host.innerHTML=`<button>${avatarHTML('role:'+speaker.id,speaker.emoji)}<span><strong>${escapeHtml(r.members?r.name+' · '+speaker.name:speaker.name)}</strong><small>${escapeHtml(m.content.slice(0,65)||'发来一个表情包')}</small></span><b>微信 ›</b></button>`;host.querySelector('button').onclick=()=>{host.hidden=true;current=r.id;go('chat');markChatSeen(r.id)};bannerTimer=setTimeout(()=>host.hidden=true,9000)}
let proactive=localRead('proactive',{enabled:false,minutes:15,roleId:'',dailyMax:12,lastAttempt:0,date:'',count:0,cursor:0}),proactiveController=null;
function proactiveDue(state,now,day){return state.enabled&&state.count<(state.date===day?state.dailyMax:Infinity)&&now-(state.lastAttempt||0)>=state.minutes*60000}
function renderProactive(){screen.innerHTML=`<section class="view">${title('主动来找你','A LITTLE MESSAGE FOR YOU')}<div class="notice">小手机打开且在前台时，角色可以主动发一条私聊。你在其他页面时会看到顶部通知。网页关闭后不后台发送。</div><form id="proactiveForm"><label class="check"><input name="enabled" type="checkbox" ${proactive.enabled?'checked':''}>开启主动消息</label><label>间隔多少分钟<input name="minutes" type="number" min="5" max="1440" value="${proactive.minutes}" required></label><label>由谁来找你<select name="roleId"><option value="">角色轮流</option>${roles.map(r=>`<option value="${r.id}" ${proactive.roleId===r.id?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><label>每天最多几条<input name="dailyMax" type="number" min="1" max="24" value="${proactive.dailyMax}" required></label><button class="primary full">保存主动消息设置</button></form><button class="secondary full" id="proactiveNow">请角色现在来找我一次</button><p class="api-note">会调用你的聊天 API。没有密钥、正在聊天、正在整理记忆或页面在后台时不发起。到期只补一条，不连续补发。当前浏览器本日已发送 ${proactive.date===PalaisCore.dateKey()?proactive.count:0} 条。</p></section>`;$('#proactiveForm').onsubmit=e=>{e.preventDefault();const f=e.target,next={...proactive,enabled:f.enabled.checked,minutes:Number(f.minutes.value),roleId:f.roleId.value,dailyMax:Number(f.dailyMax.value),lastAttempt:Date.now()};localSave('proactive',next);proactive=next;if(!next.enabled)proactiveController?.abort();toast('主动消息设置已保存')};$('#proactiveNow').onclick=async()=>{if(!requireAPI())return;const b=$('#proactiveNow');b.disabled=true;await proactiveTick(true);b.disabled=false}}
async function proactiveTick(force=false){const now=Date.now(),day=PalaisCore.dateKey();if(busy||memoryBusy||socialBusy||phoneLocked||document.hidden||!apiReady()||(!force&&(isChatView()||!proactiveDue(proactive,now,day))))return false;const r=proactive.roleId?roles.find(r=>r.id===proactive.roleId):roles[proactive.cursor%Math.max(roles.length,1)];if(!r)return false;if(proactive.date!==day){proactive.date=day;proactive.count=0}if(proactive.count>=proactive.dailyMax){if(force)toast('今天的主动消息已达到上限');return false}proactive.lastAttempt=now;localSave('proactive',proactive);const mine=new AbortController();proactiveController=mine;controller=mine;busy=true;try{const history=histories[r.id]||[],system=PalaisCore.systemPrompt(r,worldbook,history)+'\n'+memoryPrompt(r.id)+'\n'+sharedContext(r.id)+'\n'+relationshipPrompt(r.id)+'\n现在主动向用户发一条自然的私聊消息，可以关心用户或接着你们聊过的话题，1–3句话。不要编造用户刚刚说了什么，不要催促或要求马上回复。';const text=await request({...config,key},await buildChatMessages(system,[...history.slice(-30),{role:'user',content:'请现在主动发起一句聊天。'}]),700,AbortSignal.any([mine.signal,AbortSignal.timeout(45000)]));if(mine.signal.aborted||phoneLocked)return false;const m={id:crypto.randomUUID(),role:'assistant',sender:r.id,createdAt:Date.now(),proactive:true,...parseChatReply(text)};const hist=histories[r.id]||(histories[r.id]=[]);hist.push(m);try{persist()}catch(err){hist.pop();throw err}proactive.count++;proactive.cursor++;localSave('proactive',proactive);incomingMessage(r,r,m);if(isChatView()&&current===r.id)renderConversation();return true}catch(err){toast('主动消息未完成：'+friendly(err));return false}finally{busy=false;if(controller===mine)controller=null;proactiveController=null;if(isChatView()&&current===r.id)renderConversation();memoryTick()}}
window.addEventListener('DOMContentLoaded',()=>{notificationDots();setInterval(()=>proactiveTick(),30000)});
function applyRoleLike(m,actor){if(!PalaisSocial.canSee(relations,actor,m))throw Error('这个角色尚不认识动态作者');if((m.likes||[]).includes(actor))return;m.likes=[...(m.likes||[]),actor];onFeedLike(m,actor);const id='like:'+m.id+':'+actor;if(!feedEvents.some(e=>e.id===id))feedEvents.push({id,role:'user',createdAt:Date.now(),audience:feedWitness(m,{author:actor}),source:'朋友圈',content:'[朋友圈] '+chatLabel(actor)+'赞了「'+feedName(m.author)+'」的动态：'+m.text.slice(0,1200)})}
function openRoleLike(m){const eligible=roles.filter(r=>r.id!==m.author&&PalaisSocial.canSee(relations,r.id,m)&&!(m.likes||[]).includes(r.id));if(!eligible.length){toast('认识动态作者的角色已经点赞，或还没有可以互动的角色');return}const d=panel(`<form id="roleLikeForm"><h2>请角色点个赞</h2><label>选择角色<select name="actor">${eligible.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select></label><div class="actions"><button type="button" class="secondary" id="cancelRoleLike">取消</button><button class="primary">点赞</button></div></form>`);$('#cancelRoleLike').onclick=()=>d.close();$('#roleLikeForm').onsubmit=e=>{e.preventDefault();const before={likes:(m.likes||[]).slice(),notices:notices.slice(),feedEvents:feedEvents.slice()};try{applyRoleLike(m,e.target.actor.value);saveSocial();d.close();renderMoments();notificationDots();toast('角色已点赞')}catch(err){m.likes=before.likes;notices=before.notices;feedEvents=before.feedEvents;toast(err.message)}}}
